// The old version of this workflow (whatever it was doing) only ever surfaced a
// single message per conversation. Chatwoot's actual conversation-show endpoint only
// exposes `last_non_activity_message` — a single message — which is almost certainly
// what was wired up before. The real message list lives on a dedicated endpoint:
// GET /api/v1/accounts/{account_id}/conversations/{id}/messages, which is what the
// previous "Fetch Messages (Chatwoot)" HTTP Request node now calls. That endpoint
// returns { payload: [...] } (Chatwoot's default page of recent messages, newest
// activity first). We normalize each message to the shape the frontend expects and
// sort ascending by time so the thread renders oldest-to-newest, exactly like a real
// chat.
//
// Widened beyond content/message_type/sender_type/created_at to also pass through id,
// status, content_type, private, attachments and in_reply_to — these power the
// WhatsApp-style message ticks, internal-note styling, attachment rendering and
// quote-reply in the Conversations page. Field names follow Chatwoot's documented
// message object shape but haven't been checked against a live response from this
// account — if any of status/content_type/private/attachments/content_attributes come
// back differently than expected, adjust the mapping below (same "verify against live
// data" caveat the Kaspi/2GIS collector configs already carry elsewhere in this repo).
//
// message_type: 0 = incoming, 1 = outgoing, 2 = activity (Chatwoot system events like
// "conversation resolved") — activity entries are dropped here rather than shown as
// chat bubbles, since they aren't real messages.

const resp = $input.first().json;
const payload = Array.isArray(resp.payload) ? resp.payload : (Array.isArray(resp) ? resp : []);

const messages = payload
  .filter(m => m.message_type !== 2)
  .map(m => ({
    id: m.id,
    content: m.content || '',
    message_type: m.message_type,
    sender_type: m.sender_type || (m.sender && m.sender.type) || '',
    sender_name: (m.sender && m.sender.name) || '',
    created_at: m.created_at,
    status: m.status || '',
    content_type: m.content_type || '',
    private: !!m.private,
    in_reply_to: (m.content_attributes && m.content_attributes.in_reply_to) || null,
    attachments: (Array.isArray(m.attachments) ? m.attachments : []).map(a => ({
      file_type: a.file_type || '',
      data_url: a.data_url || a.file_url || '',
      thumb_url: a.thumb_url || ''
    }))
  }))
  .sort((a, b) => (a.created_at || 0) - (b.created_at || 0));

return [{ json: { messages } }];
